  const continuousNote=document.createElement('p');continuousNote.id='continuousNote';continuousNote.className='meta';continuousNote.textContent='正式模式可搜尋兩個連續變數：平面面積 A 與單一被動出口尺寸（堰寬 b 或孔口面積 Ao）。每個候選均重跑同一權威 RK4；不回寫原始工作輸入。結果不是已證明的連續全域最優解，亦非最終工程設計驗證。';optControls.appendChild(continuousNote);
  const continuousControls=document.createElement('div');continuousControls.id='continuousControls';continuousControls.innerHTML='<div class="twocol"><div><label>Continuous minimum plan area A (m²)</label><input id="contAmin" type="number" min="1" step="0.1" value="60"></div><div><label>Continuous maximum plan area A (m²)</label><input id="contAmax" type="number" min="1" step="0.1" value="600"></div></div><div id="continuousGateStatus" class="meta"></div>';optControls.appendChild(continuousControls);
  const optGuide=document.createElement('details');optGuide.className='foot';optGuide.innerHTML='<summary><strong>Declared screening bounds</strong></summary><table class="metrics"><tr><th>Variable</th><th>Declared bound / fixed condition</th><th>Role in the routing screen</th></tr><tr><td>Plan area A</td><td>60–600 m²; 20 m² increment</td><td>Defines the constant-area storage geometry. These are user-declared search bounds, not a universal validated range.</td></tr><tr><td>Weir width b</td><td>Enter a minimum and maximum (default 0.05–1.00 m). Crest elevation P and coefficient Cw remain fixed.</td><td>Changes the weir discharge capacity above its crest.</td></tr><tr><td>Opening area Ao</td><td>Enter a minimum and maximum (default 0.005–0.050 m²). Invert elevation and Cd remain fixed.</td><td>Changes the rectangular-opening discharge capacity above its invert.</td></tr><tr><td>Riser diameter D</td><td>Enter a minimum and maximum (default 0.15–0.60 m). Riser crest/invert and Cr/Cd remain fixed.</td><td>Research-inspection variable only; formal screening remains locked.</td></tr></table><p>Each selected size is tested at five equally spaced values, including its declared minimum and maximum. These bounds define only the present discrete screen; a selected feasible case is not final engineering-design validation.</p>';
