      row.innerHTML='<div style="font-weight:700;color:#102a43;text-align:right">'+name+'</div><div><div style="position:relative;height:18px;margin:0 8px;background:#9fb7c5;border-radius:6px"><span style="position:absolute;left:'+pct+'%;top:50%;width:16px;height:16px;border-radius:50%;background:#0b557d;transform:translate(-50%,-50%);border:2px solid white;box-shadow:0 0 0 1px #0b557d"></span></div><div style="display:flex;justify-content:space-between;font-size:12px;color:#526a78;margin:5px 8px 0"><span>'+a.toFixed(dec)+' '+unit+'</span><strong style="color:#102a43">'+value.toFixed(dec)+' '+unit+(searched?' (searched)':' (fixed)')+'</strong><span>'+b.toFixed(dec)+' '+unit+'</span></div></div>';
