      const local=(r,x,pass)=>{const [lo,hi,on,fixed]=r;if(!on)return[fixed];const base=(hi-lo)/4;const half=base/Math.pow(2,pass-1);return uniform(Math.max(lo,x-half),Math.min(hi,x+half),true,x);};
