      renderPhysical();if(!last)return;
      if(!formalScreeningEligible()){say(en?'Continuous numerical search was not run. Complete the same formal screening conditions first.':'尚未執行連續數值搜尋。請先完成與正式篩選相同的物理條件及可追溯紀錄。');return;}
