      syncOptimizerFromDeclared();const qlim=num('qallow'),hlim=num('hallow'),drainLimit=num('residualPct')/100;
      if(!(qlim>0&&Number.isFinite(hlim)&&hlim>=last.p.h0)){say(en?'Enter valid Qallow and Hallow before the continuous numerical search.':'請先輸入有效的 Qallow 與 Hallow，再執行連續數值搜尋。');return;}
      const active=last.p.weir?'b':'ao',a0=num('contAmin'),a1=num('contAmax'),x0=active==='b'?num('optBmin'):num('optAomin'),x1=active==='b'?num('optBmax'):num('optAomax');
      if(!(a0>0&&a1>=a0&&x0>0&&x1>=x0)){say(en?'A or active-outlet bounds are invalid.':'A 或已啟用出口尺寸的上下限無效。');return;}
      const radical=(n,base)=>{let value=0,f=1/base;while(n){value+=f*(n%base);n=Math.floor(n/base);f/=base;}return value;},map=(a,b,u)=>a+u*(b-a),rows=[],fail={outflow:0,level:0,drain:0,mass:0,boundary:0};let evaluated=0;
      const check=(A,x,phase)=>{evaluated++;const p={...last.p,area:A,bw:active==='b'?x:last.p.bw,ao:active==='ao'?x:last.p.ao};try{const z=routeDesignCandidate(p),s=Math.max(0,z.smax-z.storage0),remaining=Math.max(0,z.drainStorage-z.storage0)/Math.max(s,1e-12),margin={q:qlim-z.qmax,h:hlim-z.hmax,drain:drainLimit-remaining},ok=margin.q>=-1e-10&&margin.h>=-1e-10&&margin.drain>=-1e-10&&relativeMassResidual(z)<=.005;if(!ok){if(margin.q<0)fail.outflow++;if(margin.h<0)fail.level++;if(margin.drain<0)fail.drain++;if(relativeMassResidual(z)>.005)fail.mass++;}rows.push({p,z,s,remaining,margin,ok,phase});}catch(_){fail.boundary++;rows.push({p:{...last.p,area:A},ok:false,phase,boundary:true});}};
