      box.classList.remove('hide');o.classList.remove('hide');if(!front.length){const limits=[fail.outflow&&(en?'peak-outflow limit':'出流尖峰限制'),fail.level&&(en?'water-level limit':'最大水位限制'),fail.drain&&(en?'drain-down residual':'排空殘留限制'),fail.boundary&&(en?'declared storage boundary':'宣告蓄水邊界')].filter(Boolean),reasons=limits.join(en?', ':'、');window.dispatchEvent(new CustomEvent('dss:continuous-result',{detail:{kind:'no-feasible',limits}}));say((en?'No feasible candidate was found. Binding conditions observed: ':'沒有可行解。觀察到的限制為：')+(reasons|| (en?'routing/mass-balance condition':'路由／質量平衡條件'))+(en?'. With engineering basis, adjust pond area, weir width, or opening area. Do not arbitrarily relax Qallow, Hallow, or other declared design standards.':'。應在具工程依據下調整池面積、堰寬或開口面積；不得任意放寬 Qallow、Hallow 或其他已宣告設計標準。'));return;}
      const chosen=front.slice().sort((a,b)=>a.s-b.s||a.z.hmax-b.z.hmax||a.z.qmax-b.z.qmax)[0],nearest=rows.filter(x=>x.phase==='discrete-grid').sort((a,b)=>((a.p.area-chosen.p.area)**2+(active==='b'?(a.p.bw-chosen.p.bw)**2:(a.p.ao-chosen.p.ao)**2))-((b.p.area-chosen.p.area)**2+(active==='b'?(b.p.bw-chosen.p.bw)**2:(b.p.ao-chosen.p.ao)**2)))[0];
