      const xhead=active==='b'?'b (m)':'Ao (m²)',table=front.slice(0,20).map((x,i)=>'<tr><td>'+ (i+1)+'</td><td>'+x.p.area.toFixed(2)+'</td><td>'+(active==='b'?x.p.bw.toFixed(4):x.p.ao.toFixed(5))+'</td><td>'+x.s.toFixed(2)+'</td><td>'+x.z.hmax.toFixed(3)+'</td><td>'+x.z.qmax.toFixed(4)+'</td><td>'+x.margin.h.toFixed(3)+' m / '+x.margin.q.toFixed(4)+' m³/s</td></tr>').join('');
