      const routeRows=chosen.z.rows.filter((_,i,a)=>i===0||i===a.length-1||i%Math.max(1,Math.floor(a.length/10))===0).map(r=>'<tr><td>'+r.t.toFixed(2)+'</td><td>'+r.qi.toFixed(5)+'</td><td>'+r.qo.toFixed(5)+'</td><td>'+r.h.toFixed(4)+'</td><td>'+r.s.toFixed(3)+'</td></tr>').join('');
